SELECT , h.title AS house_title, h.cover_img AS house_cover, h.city AS house_city, h.address AS house_address, h.host_id AS host_id, u.username, u.real_name AS user_real_name, (SELECT COUNT(1) FROM review rv WHERE rv.order_id = o.id) AS reviewed FROM booking_order o LEFT JOIN house h ON o.house_id = h.id LEFT JOIN sys_user u ON o.user_id = u.id
AND o.order_no LIKE CONCAT('%', #{orderNo}, '%')
AND o.status = #{status}
AND o.user_id = #{userId}
AND h.host_id = #{hostId}
AND (o.contact_name LIKE CONCAT('%', #{keyword}, '%') OR o.contact_phone LIKE CONCAT('%', #{keyword}, '%') OR h.title LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY o.total_amount DESC ORDER BY o.creation_date DESC, o.id DESC
LIMIT #{offset}, #{pageSize}

