SELECT COUNT(1)
FROM booking_order
WHERE house_id = #{houseId}
  AND status IN (0, 1, 2)
  AND check_in_date < #{checkOut}
  AND check_out_date > #{checkIn}

SELECT IFNULL(SUM(total_amount), 0)
FROM booking_order
WHERE status IN (1, 2, 3)
  AND creation_date >= #{start}
  AND creation_date < #{end}

